/* English translations for openings, studies, Pattern Drill sets, and Threats sources. */
(function(){
"use strict";
const OPENINGS_EN = {"plans":{"e4e5":{"n":"Open Game","idea":"Both players staked a claim in the center with e4 and e5. Expect a fast fight for the center and rapid piece development.","w":["Quickly develop your knight to f3 and bishop (e.g. to c4 or b5).","Castle kingside and connect your rooks."],"b":["Defend the e5 pawn (usually with the knight to c6).","Develop your minor pieces and prepare to castle."]},"italian":{"n":"Italian Game","idea":"White aims the bishop on c4 straight at the weak f7 square next to Black's king.","w":["Prepare d4 with c3 (or play quietly with d3) and strike in the center.","Keep an eye on f7 – after castling you can also attack with a knight or rook via e1."],"b":["Develop the bishop to c5 or knight to f6 and castle quickly.","Guard the f7 square and the central d5 square."]},"evans":{"n":"Evans Gambit","idea":"White sacrifices a pawn on b4 to gain time for c3 and d4 and launch a fast attack on the king.","w":["Play c3 and d4 quickly, open the center, and attack the uncastled king.","Don't let Black finish development in peace."],"b":["If you take the pawn, develop fast and give it back at the right moment for king safety.","Play ...Bb6 or ...Ba5 and prepare to castle."]},"twoknights":{"n":"Two Knights Defense","idea":"Instead of ...Bc5, Black immediately attacks the e4 pawn with the knight on f6. Play often gets very sharp.","w":["You can play calmly with d3 and castle, or sharply with Ng5 targeting f7.","With Ng5, be ready for ...d5 and ...Na5."],"b":["After Ng5, answer with ...d5 (not ...Nxe4? or careless moves that ignore f7).","If White plays d3, calmly develop your bishop and castle."]},"spanish":{"n":"Ruy Lopez (Spanish Game)","idea":"White's bishop on b5 puts pressure on the c6 knight that defends e5, building long-term central pressure.","w":["Castle, play Re1, c3, and d4, and take over the center.","After ...a6, tuck the bishop back to a4 and later b3 or c2."],"b":["Chase the bishop with ...a6, develop the knight to f6 and bishop to e7.","Prepare to castle and firmly defend the e5 pawn."]},"scotch":{"n":"Scotch Game","idea":"White opens the center right away on move 3 with d4. Fast, open play with no waiting around.","w":["Open the center, bring pieces into the middle, and attack the king.","After ...Bc5 or ...Nf6, place your bishops and knights actively."],"b":["Capture on d4 and develop actively (...Bc5, ...Nf6).","Don't let White grab a ton of space for free."]},"fourknights":{"n":"Four Knights Game","idea":"Both players develop both knights first. A solid, calm, and safe opening.","w":["Finish development with the bishops (Bb5 or Bc4), castle, and open the center with d4.","Look for small improvements in piece placement."],"b":["Develop your bishops (...Bb4 or ...Bc5) and castle.","Keep the balance in the center of the board."]},"petrov":{"n":"Petrov's Defense (Russian Game)","idea":"Instead of defending e5, Black immediately counterattacks White's e4 pawn.","w":["Take on e5, retreat Nf3 after ...d6, and play d4 for a nice center.","Watch for the trap: after Nxe5 Nxe4?? Qe2! wins a piece."],"b":["After Nxe5, first kick the knight with ...d6 before taking on e4.","Develop your pieces quickly and castle."]},"philidor":{"n":"Philidor Defense","idea":"Black defends e5 with the d6 pawn. It's solid, but Black's f8 bishop has less room.","w":["Play d4 and Bc4 to gain space in the center and develop fast.","Press in the center and use your freer pieces."],"b":["Keep a solid center on e5, develop knights to f6 and d7, and prepare to castle.","Don't open the position before your king is safe."]},"vienna":{"n":"Vienna Game","idea":"White guards e4 with the c3 knight, keeping the f-pawn free for an attack with f4 or Bc4.","w":["Develop the bishop to c4 and prepare f4 on the kingside when the moment is right.","Play actively against f7."],"b":["The best counter is ...Nf6 and a timely central break with ...d5.","Don't give White a comfortable kingside attack."]},"kingsgambit":{"n":"King's Gambit","idea":"White sacrifices the f4 pawn to open the f-file for the rook and dominate the center with d4.","w":["Play Nf3, Bc4, and d4 and attack fast down the open f-file.","Don't allow Black a nasty queen check on h4."],"b":["Watch out for checks and attacks on f7 – either take the pawn and develop fast, or play ...d5.","Keep your king safe and don't fall behind in development."]},"center":{"n":"Center Game","idea":"White opens the center on move 2 with d4. After ...exd4, White often recaptures with the queen or gambits a pawn.","w":["Develop rapidly (Bc4, Nf3), and if your queen is on d4, watch out for losing time to ...Nc6.","In the Danish Gambit, aim both bishops at the kingside."],"b":["Take on d4 and gain time by attacking White's queen (...Nc6) while developing quickly.","Give back a pawn if it buys you safety and a lead in development."]},"bishop":{"n":"Bishop's Opening","idea":"White aims the bishop at c4 right away, targeting f7. Often transposes into the Italian or Vienna Game.","w":["Target f7, develop your knights, and prepare a central push or f4.","Keep your pieces active."],"b":["Play ...Nf6 or ...Bc5 and strike in the center with ...d5 at the right time.","Stay alert to early attacks on f7."]},"sicilian":{"n":"Sicilian Defense","idea":"The most fighting answer to 1. e4! Black fights for d4 from the flank, creating unbalanced and sharp play.","w":["In the Open Sicilian (Nf3 and d4), grab space, develop fast, and attack the king.","With queenside castling (O-O-O), launch a kingside pawn storm."],"b":["Use the half-open c-file for your rook and attack on the queenside.","Play ...d5 at the right moment to equalize the center."]},"french":{"n":"French Defense","idea":"Black prepares ...d5 with ...e6. A sturdy fortress, though Black's light-squared bishop on c8 starts out hemmed in.","w":["Claim the center (d4) and attack on the kingside or use your extra space.","Protect your d4 pawn from Black's pressure."],"b":["Attack White's center with ...c5 and ...Nc6 (and sometimes ...f6).","Look for a way to bring the c8 bishop into the game."]},"carokann":{"n":"Caro-Kann Defense","idea":"Black prepares ...d5 with ...c6. A very solid defense that doesn't block in the c8 bishop.","w":["Gain central space (d4, e5, or Nc3) and look for a kingside attack.","Don't let Black easily trade off all passive pieces."],"b":["Develop the light-squared bishop to f5 or g4 before playing ...e6.","Then back up the center solidly with ...e6 and ...c5."]},"scandinavian":{"n":"Scandinavian Defense","idea":"Black challenges White's e4 pawn right on move 1 with ...d5.","w":["After exd5 Qxd5, develop the knight to c3 attacking the queen to gain a lead in development.","Take over the center and attack while Black is still catching up."],"b":["If you recapture with the queen, retreat it to a safe square (a5, d6, or d8) after Nc3.","Finish development (...c6, ...Nf6, ...Bf5/Bg4) and castle."]},"pirc":{"n":"Pirc / Modern Defense","idea":"Black lets White occupy the center first and fianchettoes the bishop on g7 to snipe at the center from afar.","w":["Build a strong center (e4, d4), develop your pieces, and prepare a kingside attack.","Watch out for counterstrikes with ...c5 or ...e5."],"b":["Put the bishop on g7, castle, and then strike White's center with ...c5 or ...e5.","Let White overextend, then tear the center apart."]},"alekhine":{"n":"Alekhine's Defense","idea":"Black lures White's pawns forward by attacking e4 on move 1 with ...Nf6.","w":["Advance your pawns sensibly (e5, d4), but be careful not to let your center crumble.","Develop your pieces right behind your pawns."],"b":["Once White's pawns advance too far, attack them with ...d6 and ...c5.","Break down White's center before it squeezes you."]},"d4d5":{"n":"Closed Game","idea":"Both players occupy the center with d4 and d5. Play is calmer and more positional – good piece placement matters most.","w":["Add pressure to d5 with c4 (Queen's Gambit) or set up solidly with Bf4/e3.","Fight for control of e4 and c5."],"b":["Hold the center firmly on d5 (with ...e6 or ...c6).","Develop your pieces and don't forget the c8 bishop."]},"qg":{"n":"Queen's Gambit","idea":"White offers the c4 pawn to challenge Black's d5 pawn and win the center. (It's not a real sacrifice – White can easily win the pawn back.)","w":["Press against d5, develop knights to c3 and f3, and prepare e4 in the center.","Use the half-open c-file for your rook."],"b":["Defend d5 with ...e6 or ...c6, or take the pawn (...dxc4) and develop quickly.","Counterstrike with ...c5 or ...e5 at the right time."]},"qgd":{"n":"Queen's Gambit Declined","idea":"Black holds the d5 center firmly with ...e6. A rock-solid setup, though the c8 bishop needs time to get out.","w":["Develop the bishop to g5 or f4, castle, and prepare pressure on the queenside or center.","Make use of your extra space."],"b":["Castle and free your position with ...c5 or ...b6 and ...Bb7.","Defend the center patiently and wait for your counterplay."]},"qga":{"n":"Queen's Gambit Accepted","idea":"Black captures on c4 to release central tension, without trying to cling to the extra pawn at all costs.","w":["Play e3 or e4 and win the pawn back with Bxc4 while building a strong center.","Develop your pieces quickly and castle."],"b":["Don't desperately defend c4 with ...b5? (a4! breaks it apart).","Instead, develop fast (...Nf6, ...e6, ...c5) and strike White's center."]},"slav":{"n":"Slav Defense","idea":"Black defends d5 with c6 so the light-squared c8 bishop stays free. Solid and flexible.","w":["Develop knights to f3 and c3, play e3 or Bf4, and fight for the center.","Control the e5 square."],"b":["Develop the bishop to f5 or g4 before playing ...e6.","Then play ...e6 and at the right moment ...c5 or ...dxc4 with ...b5."]},"london":{"n":"London System","idea":"White builds a sturdy pawn pyramid (d4, e3, c3) and develops the bishop to f4 outside the chain. Simple and reliable.","w":["Set up Bf4, e3, c3, Nf3, Bd3, and Nbd2, then castle and aim for e5 or a kingside attack.","Watch out for an early ...c5 and ...Qb6 from Black."],"b":["Challenge White's center and queenside with ...c5 and ...Nc6 (often ...Qb6 too).","Don't let White peacefully build a kingside attack."]},"colle":{"n":"Colle System","idea":"White builds a solid d4, e3, Bd3, Nf3, c3 setup and aims to open the game later with the e4 break.","w":["Prepare e4 (with Bd3, Nbd2, Re1) and attack on the kingside once the center opens.","Play patiently and safely."],"b":["Prevent or meet the e4 break and develop actively (...c5, ...Nc6).","Take advantage of White's hemmed-in c1 bishop on the queenside."]},"trompowsky":{"n":"Trompowsky Attack","idea":"White attacks the f6 knight on move 2 with Bg5, aiming to double Black's pawns or take Black out of book.","w":["Decide whether to trade on f6 (doubling Black's pawns) or retreat to h4/f4.","Develop fast and fight for the center."],"b":["Respond actively (...Ne4, ...c5, or ...d5) instead of letting your structure be ruined easily.","Use the bishop pair if White takes on f6."]},"kid":{"n":"King's Indian Defense","idea":"A fierce fighting defense against 1. d4! Black lets White claim the center, puts the bishop on g7, castles, and then strikes back.","w":["Gain space on the queenside (c4, Nc3, b4–b5) and slow down Black's kingside attack.","Watch out for ...e5 or ...f5 breaks on the kingside."],"b":["After castling, prepare the ...e5 or ...c5 break.","If the center locks up, storm the kingside with ...f5, ...f4, and your pawns!"]},"grunfeld":{"n":"Grünfeld Defense","idea":"Black hands over the pawn center to bombard it with the g7 bishop and active pieces.","w":["Build a powerful pawn center (c4, d4, e4) and defend it from Black's piece pressure.","Don't let Black shatter your central pawns."],"b":["Fire at White's center with the g7 bishop and attack it with ...c5 and ...Nc6.","Play actively with your pieces."]},"nimzo":{"n":"Nimzo-Indian Defense","idea":"Black pins White's c3 knight with ...Bb4 and fights for control of the e4 square.","w":["Play for the bishop pair (Qc2 or e3), reinforce the center, and prepare e4.","Don't let Black blockade your pawns on c4."],"b":["Control e4, trade on c3 at the right moment, and target the doubled c4 pawn.","Stay flexible in the center (...d5 or ...c5)."]},"qid":{"n":"Queen's Indian Defense","idea":"Black fianchettoes the bishop on b7 to control the key e4 square from a distance.","w":["Claim central space with g3, Bg2, d5, or e4 and blunt the b7 bishop.","Castle and build pressure down the c-file."],"b":["Control e4 with the b7 bishop and f6 knight.","Prepare ...c5 or ...d5 to open the diagonal for the b7 bishop."]},"benoni":{"n":"Benoni Defense","idea":"Black immediately attacks d4 with ...c5, leading to unbalanced play: White attacks in the center, Black on the queenside.","w":["Push d5, claim space, and prepare the e4–e5 break in the center.","Keep an eye on Black's queenside pawn majority (...b5)."],"b":["Use your queenside pawn majority (...a6, ...b5) and the strong g7 bishop.","Put pressure on White's e4 pawn."]},"dutch":{"n":"Dutch Defense","idea":"Black fights for e4 with ...f5 – a sharp opening that slightly loosens the kingside.","w":["Play g3, Bg2, c4, and Nc3 and target Black's weak light squares.","Stay alert to Black's kingside attack."],"b":["Aim pieces at e4 (Bg7 or Be7, Nf6), castle, and attack on the kingside.","Reclaim control of the e4 square."]},"english":{"n":"English Opening","idea":"White starts with the flank move 1. c4, controlling d5 while keeping central options open.","w":["Often fianchetto the bishop on g2, put the knight on c3, and press on the queenside.","Control the key d5 square."],"b":["Answer with ...e5 (Reversed Sicilian), ...c5 (Symmetrical), or ...e6 with ...d5.","Fight for the central squares d4 and e4."]},"reti":{"n":"Réti Opening","idea":"White starts with Nf3 without revealing plans too soon, attacking the center from afar with g3 and Bg2.","w":["Place the bishop on g2, challenge the opponent's center with c4, and keep the position flexible.","Castle and adapt to what Black sets up."],"b":["Occupy the center with pawns (...d5, or ...c5 / ...e5) and develop calmly.","Don't let White easily undermine your center."]},"catalan":{"n":"Catalan Opening","idea":"Combines the Queen's Gambit (d4, c4) with a powerful bishop on g2 firing down the whole long diagonal.","w":["Use the g2 bishop to pressure Black's queenside and the d5 square.","Play patiently – even if you gambit the c4 pawn, you get huge pressure."],"b":["Defend the queenside solidly, develop quickly, and castle.","Look to free your game with ...c5 or ...dxc4."]},"bird":{"n":"Bird's Opening","idea":"White starts with 1. f4 to control e5, while taking care not to weaken the king too much.","w":["Control e5 (Nf3, e3/g3, b3, Bb2) and prepare a kingside attack.","Don't forget your own king's safety."],"b":["Play ...d5, ...g6, or the sharp From's Gambit (1...e5!).","Target the weakened e1–h4 diagonal."]},"polish":{"n":"Polish (Sokolsky) Opening","idea":"A rare and playful opening: 1. b4! White wants to put the bishop on b2 fast and surprise the opponent.","w":["Put the bishop on b2 and aim at the central e5 square and the kingside.","Watch the b4 pawn so Black doesn't win it for free."],"b":["Occupy the center (...e5, ...d5) and challenge the b4 pawn.","Calm development gives Black a very good game."]}},"book":["Open Game","Open Game (2. Nf3 Nc6)","Italian Game","Italian Game: Giuoco Piano","Italian Game: Classical Variation (c3)","Italian Game: Giuoco Pianissimo","Italian Game: Evans Gambit","Evans Gambit Accepted","Two Knights Defense","Two Knights Defense: Ng5 Attack on f7","Two Knights Defense: Modern Variation (d3)","Italian Game: Hungarian Defense","Ruy Lopez (Spanish Game)","Ruy Lopez: Morphy Defense","Ruy Lopez: Morphy Defense (3...a6 4. Ba4 Nf6)","Ruy Lopez: Closed Variation","Ruy Lopez: Exchange Variation","Ruy Lopez: Berlin Defense","Scotch Game","Scotch Game: Main Line","Scotch Gambit","Four Knights Game","Four Knights Game: Spanish Variation","Four Knights Game: Italian Variation","Petrov's Defense (Russian Game)","Petrov's Defense: Classical Variation","Philidor Defense","Philidor Defense: Main Line","Vienna Game","Vienna Game: Falkbeer Variation","Vienna Game: Bishop on c4","King's Gambit","King's Gambit Accepted","King's Gambit Declined (Classical)","King's Gambit: Falkbeer Countergambit","Center Game","Center Game: Queen on d4","Danish Gambit","Bishop's Opening","Sicilian Defense","Open Sicilian Defense","Sicilian Defense: Najdorf Variation","Sicilian Defense: Dragon Variation","Sicilian Defense: Scheveningen Variation","Sicilian Defense: Open with 2...Nc6","Sicilian Defense: with 2...e6","Sicilian Defense: Alapin Variation (c3)","Closed Sicilian Defense","Sicilian Defense: Bowdler Attack (Bc4)","French Defense","French Defense: Main Position","French Defense: Exchange Variation","French Defense: Advance Variation","French Defense: Tarrasch Variation","French Defense: Winawer Variation","French Defense: Classical Variation","Caro-Kann Defense","Caro-Kann Defense: Main Position","Caro-Kann: Exchange Variation","Caro-Kann: Advance Variation","Caro-Kann: Classical Variation","Scandinavian Defense","Scandinavian Defense: Queen Capture (2...Qxd5)","Scandinavian Defense: Modern Variation (2...Nf6)","Pirc Defense","Pirc Defense: Classical","Modern Defense","Alekhine's Defense","Alekhine's Defense: Main Line","Closed Game (1. d4 d5)","Queen's Gambit","Queen's Gambit Declined","Queen's Gambit Declined: with Bg5","Queen's Gambit Accepted","Slav Defense","Slav Defense: Main Line","Semi-Slav Defense","London System","London System (with Nf3)","London System","London System (vs ...Nf6)","Colle System","Trompowsky Attack","Indian Game (1. d4 Nf6)","King's Indian Defense","King's Indian Defense: Classical","Grünfeld Defense","Nimzo-Indian Defense","Queen's Indian Defense","Catalan Opening","Benoni Defense","Modern Benoni","Dutch Defense","Dutch Defense: Classical / Leningrad","English Opening","English Opening: Reversed Sicilian","English Opening: Symmetrical Variation","Réti Opening","Réti Opening: Main Line","Bird's Opening","Polish (Sokolsky) Opening"]};
const STUDIES_EN = {"tactics":{"name":"Tactics Basics","intro":"Essential chess tactics: pin, fork, skewer, smothered mate, forcing checks, and the rule of the square. Practice more in Pattern Drill.","chapters":{"pin1":{"title":"The pin: a pinned pawn does not defend","intro":"A pin happens when a piece cannot move because something more valuable is standing behind it, like the king. Look at the diagonal from your bishop on e5 all the way to the black king on h8. The g7 pawn is standing on it. That pawn is pinned: if it moved, the bishop would put the king in check. A pinned piece pretends to defend, but really it defends nothing at all.","moves":[{"q":"The g7 pawn is pinned. So you can capture the h6 pawn, even though it looks like g7 protects it.","c":"1.Qxh6+! The g7 pawn cannot capture because it is pinned by the e5 bishop."},{"c":"1…Kg8. The king has to step aside."},{"q":"Queen and bishop working together. Deliver checkmate!","c":"2.Qxg7#. The queen on g7 is protected by the e5 bishop. Checkmate!"}],"end":"Before every move, check which of your opponent's pieces are pinned. A pinned defender cannot protect anything, so you can capture even where it looks dangerous."},"pin2":{"title":"The pin: attack the pinned piece","intro":"Your rook on g4 is looking down the g-file straight at the black king. Between them stands the g7 bishop. The bishop is pinned: it cannot move away, or the rook would give check to the king. A pinned piece is tied to a post. When you attack it, it cannot run away.","moves":[{"q":"The g7 bishop cannot run away. Attack it with a pawn!","c":"1.f6! The pawn attacks the bishop. The bishop is pinned, so it cannot escape."},{"c":"1…Kf8. The king stepped off the g-file and unpinned the bishop. Too late, though!"},{"q":"Capture the bishop!","c":"2.fxg7+. White wins a whole bishop, and the g7 pawn is almost ready to promote."},{"c":"2…Kg8. The black king has to come back and guard the promotion square."}],"end":"When your opponent's piece is pinned, don't wait. Add another attacker, best of all a pawn. A pinned piece cannot run away and will be lost."},"fork":{"title":"Pawn fork","intro":"From the game Belavenets – N.N., 1936. A fork is when one piece attacks two enemy pieces at the same time. Your opponent can only save one of them. The cheapest fork is a pawn fork: a pawn is worth the least, so your opponent will lose a much bigger piece, like a knight or bishop. Look at Black's knight on e6 and bishop on g6. They are one square apart.","moves":[{"q":"Black's knight on e6 and bishop on g6 stand side by side on the 6th rank. Which pawn wants to jump right between them?","c":"1.f4! You threaten f5, forking both the knight and the bishop."},{"c":"1…f5. Black stops your pawn with his own pawn."},{"q":"The f5 pawn blocked the road. Attack it with another pawn!","c":"2.g4! The pawn attacks f5. Whether Black takes or pushes, your f4 pawn will move forward."},{"c":"2…fxe4. Black captured the pawn."},{"q":"Now the road is clear. Play the fork!","c":"3.f5! The pawn attacks both the e6 knight and the g6 bishop. Black is going to lose a piece."}],"end":"A fork means one piece attacking two. When enemy pieces stand one square apart, look for a pawn that can step between them. If your opponent blocks the way, knock down the blocker with another pawn."},"skewer":{"title":"Skewer: attacking through a piece","intro":"Your a7 pawn is one step from promoting, but your own rook on a8 is blocking its way. If the rook just moves away, Black's rook on a5 will take the pawn. A trick called a skewer (like an X-ray) will help: you attack a piece, and behind it stands another piece that you will capture next.","moves":[{"q":"Clear the way for your pawn. Where should the rook go so you also threaten promotion?","c":"1.Rh8! You threaten a8=Q. If Black's rook takes the pawn, it lands on the same rank as its king."},{"c":"1…Rxa7. Black took the pawn. Now the f7 king and a7 rook are on the 7th rank together."},{"q":"The king and rook are on the same rank. Give check so you attack the rook right through the king!","c":"2.Rh7+! The king must move out of the way, leaving the a7 rook open."},{"c":"2…Ke6. The king stepped aside."},{"q":"Take the rook!","c":"3.Rxa7. White wins a rook and the game is won."}],"end":"Skewer: you attack a more valuable piece (like the king), and when it moves out of the way, you capture the piece standing behind it. Always look for it when two enemy pieces line up."},"smother":{"title":"Smothered mate","intro":"From the game Atkins – Gibson, Southport 1924. Black's king on h8 is surrounded by its own pieces. It has nowhere to run. All it takes to beat a king like that is one check from a knight. It is called a smothered mate: the king is smothered by its own pieces.","moves":[{"q":"Sacrifice your queen to fill up the king's last empty square.","c":"1.Qg8+!! The king cannot take the queen because the b3 bishop protects her. The rook has to take."},{"c":"1…Rxg8. The rook filled the g8 square. Now the king is completely walled in."},{"q":"Now bring in the knight!","c":"2.Nf7#. Smothered mate! The king has nowhere to go, and nobody can take the knight."}],"end":"When the king is tucked in the corner with its own pieces around it, look for a knight check. Sometimes you need to sacrifice a piece first to fill the king's last escape square."},"checks":{"title":"Check after check to checkmate","intro":"From the game Tolush – Randviir, Pärnu 1947. A check is a strong move because your opponent must answer it right away and has no time for anything else. When one check follows another, you can lure the king into a checkmate trap. Black's king on f6 is out in the middle, surrounded by your pieces.","moves":[{"q":"Give check with the d1 rook and let Black capture your e5 rook.","c":"44.Rd6+! The king has nowhere to run. Black could block with the knight on e6, but it would fall right away. So the king takes the e5 rook."},{"c":"44…Kxe5. The king marched even farther forward."},{"q":"Another check! Jump the knight so the king has to go to f5.","c":"45.Nf7+. The king must go to f5 because the f3 pawn guards e4."},{"c":"45…Kf5."},{"q":"And now checkmate with a pawn!","c":"46.g4#. The pawn delivered checkmate! The king is trapped by the rook, knight, and pawns."}],"end":"A series of checks gives your opponent no time to breathe. Always look at every check you have. Sometimes you sacrifice a piece to bring the king right where you can checkmate it."},"square":{"title":"The rule of the square","intro":"Can Black's king catch your pawn? You don't have to count move by move! Picture a square in your head: one side goes from the pawn to its promotion square, and the square stretches out just as wide toward the king. If the king is inside the square, it catches the pawn. If it is outside, it can never catch it. Careful: a pawn on h2 can jump two squares, so its square is counted as if it stood on h3.","moves":[{"q":"Black's king on b6 is just outside the square. Which pawn move lets you get away?","c":"1.h4! The pawn jumped two squares. The square goes from h4 to d8, and the b6 king is outside it."},{"c":"1…Kc5. The king starts chasing."},{"q":"Keep going!","c":"2.h5. The square shrank, and the c5 king is still outside it."},{"c":"2…Kd6."},{"q":"Keep pushing.","c":"3.h6."},{"c":"3…Ke7."},{"q":"One more step.","c":"4.h7."},{"c":"4…Kf7. The king arrived one move too late."},{"q":"Promote the pawn to a queen!","c":"5.h8=Q. A brand-new queen! The king couldn't make it in time."}],"end":"Rule of the square: draw a square from the pawn to the promotion square. If the enemy king is inside the square (or steps in on its turn), it catches the pawn. If it is outside, the pawn promotes. A pawn on the 2nd rank counts as if it were one square ahead."},"unfork1":{"title":"Beating a fork 1: defend both pieces","intro":"Black's queen on f5 is attacking both your b1 rook and your f3 knight at the same time. That's a fork. But don't give up! There are eight clever ways to fight back against a fork. Way 1: find a single move that defends both attacked pieces at once.","moves":[{"q":"Find a move that leaves both the b1 rook and the f3 knight defended.","c":"1.Qd1! From d1, the queen defends the b1 rook along the 1st rank and the f3 knight along the diagonal. You lose nothing! Playing 1.Kg2? Qxb1 or 1.Rxb7? Qxf3 would lose a piece."},{"c":"1…Qe4. Black keeps trying, but everything is safe."}],"end":"Way 1 to beat a fork: find one move that protects both attacked pieces at the same time."},"unfork2":{"title":"Beating a fork 2: escape with check","intro":"Black's knight on c2 is attacking both your e3 queen and your a1 rook. If the queen just runs away, the knight will take the rook. Way 2: move one attacked piece away with check. Your opponent has to deal with the check, giving you time to save the second piece.","moves":[{"q":"Where can your queen go while giving check?","c":"1.Qe6+! The queen escaped and gave check. Black has no time to take the rook."},{"c":"1…Kh8."},{"q":"The king stepped aside. Now save the a1 rook.","c":"2.Rad1. The rook is safe, and the c2 knight is now stuck alone in your camp. If you had played 1.Qf3?, Nxa1 would win your rook."},{"c":"2…c6."}],"end":"Way 2 to beat a fork: move an attacked piece away with check. The check buys you time to save the other piece."},"unfork3":{"title":"Beating a fork 3: one defends the other","intro":"Black's queen on d5 is attacking both your b3 rook and your g5 knight. Way 3: move one of the attacked pieces to a safe square where it also protects the other piece.","moves":[{"q":"Where can the rook go so it is safe and also defends the g5 knight?","c":"1.Rg3! The rook escaped from b3 and now protects the g5 knight. It looks like 1.Qe3 defends both too, but after 1…Rce8 Black's rook attacks the queen and something still drops."},{"c":"1…Rfe8. Both of your pieces are safe."}],"end":"Way 3 to beat a fork: move one attacked piece so that it defends the other one."},"unfork4":{"title":"Beating a fork 4: escape with a threat","intro":"Black's knight on c2 is attacking your e3 queen and your a1 rook. Way 4: move one attacked piece away while creating a threat of your own. Your opponent has to answer your threat, and you win time.","moves":[{"q":"Where can the queen move to attack something of Black's?","c":"1.Qf3! The queen escaped and attacked the a8 rook. If Black takes your rook with 1…Nxa1?, then 2.Qxa8 wins for White."},{"c":"1…Rb8. Black had to save the rook."},{"q":"The rook ran away. Now attack the c2 knight.","c":"2.Bd3! The bishop attacks the c2 knight."},{"c":"2…Nxd4. The knight escaped and grabbed a pawn, but your a1 rook is saved."}],"end":"Way 4 to beat a fork: run away while making a threat. When your opponent has to stop your threat, they don't have time to take your piece."},"unfork5":{"title":"Beating a fork 5: sacrifice your way out","intro":"Black's bishop on b4 is attacking both your d2 queen and your a5 rook. The bishop is guarded by the d5 knight. Way 5: sometimes you can break out of a fork with a sacrifice. Remove the defender of the piece doing the forking!","moves":[{"q":"Who is guarding the b4 bishop? Remove that defender!","c":"1.Rxd5! The rook captured the knight that was defending the b4 bishop."},{"c":"1…Qe7."},{"q":"Black's queen tries to get away. How do you save your rook and win the bishop too?","c":"2.Rd7!! Another sacrifice! The queen has to take, leaving the b4 bishop undefended."},{"c":"2…Qxd7. Now you capture the b4 bishop and get two minor pieces for a rook – a great trade!"}],"end":"Way 5 to beat a fork: sacrifice your way out. Remove the defender of the forking piece so it falls."},"unfork6":{"title":"Beating a fork 6: pin the forker","intro":"Black's d4 pawn is attacking both your c3 queen and your e3 knight. Way 6: pin the piece that is giving the fork! Once it cannot move, it cannot take anything. Look at what is standing behind the d4 pawn on the same rank.","moves":[{"q":"What is standing behind the d4 pawn on the 4th rank? Put your queen where the pawn cannot capture.","c":"1.Qc4! The queen attacks the d4 pawn, and behind it on the 4th rank stands Black's queen on h4. The pawn is pinned: if it took 1…dxe3?, then 2.Qxh4 wins Black's queen! Playing 1.Qd2? dxe3 would lose the knight."},{"c":"1…Bh7. Black's bishop stepped out of the way."},{"q":"Now save your knight and attack the d4 pawn with it.","c":"2.Nc2! The knight escaped and attacked the d4 pawn again."},{"c":"2…Qf4. Black defends the pawn, but White takes it with 3.Nxd4 – material is equal and the fork is gone."}],"end":"Way 6 to beat a fork: pin the forking piece. A pinned piece cannot capture because it would expose something even more valuable."},"unfork7":{"title":"Beating a fork 7: desperado","intro":"Black's knight on e4 is attacking your c3 queen and your g3 rook. You cannot save both. Way 7: desperado! A piece that is doomed anyway tries to sell itself for the highest price – grabbing something before it goes down.","moves":[{"q":"The g3 rook is a goner. What can it take before it falls?","c":"1.Rxg6+! Since the rook was going to be lost anyway, it took a bishop – and with check! Playing 1.Qb3? or 1.Bg5? Nxg3+ would lose the rook for nothing."},{"c":"1…hxg6. If Black's king had moved (1…Kf7 or 1…Kf8), then 2.Qg7+ would lead to a quick checkmate."},{"q":"Now save the queen.","c":"2.Qb3. The queen is safe. White traded a rook for a bishop, but Black's king is wide open now and White's pieces stand much better."},{"c":"2…Ndc5. The game goes on and White has the better position."}],"end":"Way 7 to beat a fork: desperado. When a piece cannot be saved, make it capture something first – best of all with check!"},"unfork8":{"title":"Beating a fork 8: escape with a mate threat","intro":"Black's knight on e3 is attacking your c2 queen, your f1 rook, and your c4 bishop all at once. It looks terrible! Way 8: move an attacked piece away while threatening checkmate. Your opponent has to save their king and won't have time to take your pieces.","moves":[{"q":"Where can the queen go to threaten checkmate on g7? Hint: the f7 pawn is pinned.","c":"1.Qg6!! The queen threatens 2.Qxg7 checkmate (protected by the c3 bishop). The f7 pawn cannot take her because it is pinned to the g8 king by the c4 bishop! Moves like 1.Qd3?, 1.Qe2?, or 1.Qf2? would lose the rook or bishop to the knight."},{"c":"1…Nf5. The knight hurried back to defend g7. Otherwise (for example 1…d5), 2.Qxg7 is checkmate."},{"q":"The knight guards g7. Give check and capture something.","c":"2.Qxf7+! The queen took a pawn with check."},{"c":"2…Kh8."},{"q":"Which black piece is undefended now?","c":"3.Qxd7. The queen captured the bishop too. White won a piece and keeps attacking."},{"c":"3…Qc6. Black wants to trade queens, but White is a whole piece ahead."}],"end":"Way 8 to beat a fork: escape with a checkmate threat. When your opponent has to rescue their king, they can't take your pieces. Victory snatched from the jaws of defeat!"},"unpin1":{"title":"Beating a pin 1: pin the pinner","intro":"Black's bishop on c5 has pinned your d4 queen to your g1 king. The d7 knight protects the bishop, so your queen cannot take it, and she cannot move out of the pin. Way 1 to beat a pin: pin the piece that is doing the pinning!","moves":[{"q":"Is Black's c5 bishop on the same file as Black's king? Pin it!","c":"1.Rc2! The rook pinned the c5 bishop to the c8 king. If the bishop takes your queen, Black's king would be in check – which is illegal. Your queen is saved! Watch out for 1.Rc1?, because Qxc1+ wins the rook."},{"c":"1…b6. Black defends the bishop, and White has the better game."}],"end":"Way 1 to beat a pin: pin the pinner. When your opponent's bishop is pinned too, it cannot capture your piece."},"unpin2":{"title":"Beating a pin 2: block the pin","intro":"Black's bishop on f7 has pinned your c4 knight to your a2 king. If Black plays b5, the knight won't be able to run away. Way 2 to beat a pin: put a piece or a pawn in between.","moves":[{"q":"Put a pawn between the knight and the king.","c":"1.b3! The pawn blocked the pin. Now the c4 knight is free to move again. If you had played 1.Kb3?, b5 would win your knight."},{"c":"1…Bd5. Black keeps attacking, but now you can save your knight."}],"end":"Way 2 to beat a pin: block it. Placing a piece or pawn between the pinner and the king breaks the pin."},"unpin3":{"title":"Beating a pin 3: sacrifice your way out","intro":"Black's bishop on g6 has pinned your d3 rook to your c2 king. Both the c5 knight and the d6 queen are attacking the rook. Way 3 to beat a pin: sacrifice a piece to capture the one doing the pinning.","moves":[{"q":"Which black piece is pinning the d3 rook? Capture it!","c":"1.Qxg6! The queen took the pinning bishop. The pin is gone, and now the d3 rook attacks Black's queen! Playing 1.Nc1? Nxd3 would lose the pinned rook."},{"c":"1…hxg6. Black took the queen. But now…"},{"q":"The d3 rook is no longer pinned. What can it take?","c":"2.Rxd6! Free from the pin, the rook captures Black's queen."},{"c":"2…Rxd6. White plays 3.Rxd6 and ends up winning a bishop – and the c6 pawn is hanging too."}],"end":"Way 3 to beat a pin: sacrifice your way out. Capture the pinning piece, even if you give up something valuable. Once the pin disappears, the unpinned piece strikes back!"},"unpin4":{"title":"Beating a pin 4: fork the pinner","intro":"Black's bishop on a5 has pinned your c3 knight to your e1 king. You cannot save the knight anymore. Way 4 to beat a pin: set up a fork against the pinning piece. Even the king can make a fork!","moves":[{"q":"The king is lined up with the a5 bishop. Where should it step to get closer to c3?","c":"1.Ke2! The king steps out of the pin. When the bishop takes the knight, the king will attack it. Playing 1.Ra4? Bxc3+ with check, or 1.Rxa5? Nxa5, would give up a rook for a bishop."},{"c":"1…Bxc3. Black captured the knight."},{"q":"The king can attack two black pieces at once. Where should it go?","c":"2.Kd3! A king fork: attacking both the c3 bishop and the c4 knight!"},{"c":"2…Rb4. The rook protects the c4 knight, but not the bishop. White takes 3.Kxc3 and material is equal again."}],"end":"Way 4 to beat a pin: fork the pinner. Sometimes you can't save the pinned piece, but a fork wins a piece right back – and even the king can help!"}}},"endgame":{"name":"Essential Endgames","intro":"Essential endgames: opposition, outflanking, king and pawn, rook pawns, and basic rook endgames.","chapters":{"opp":{"title":"Opposition: who has to step aside","intro":"When only kings are left on the board, the king becomes a fighter. Kings cannot touch each other, so they push each other back. When they stand face-to-face with one, three, or five empty squares between them, the player whose turn it is has to step to the side. That means their opponent has the opposition. Your king wants to reach f8, g8, or h8, and Black's king will try to stop you. First, learn how to keep the opposition.","moves":[{"q":"There are six empty squares between the kings. Step straight toward the black king.","c":"1.Ka2! Now there are five squares between the kings, and it is Black's turn. You have the opposition!"},{"c":"1…Kb8! A clever move. Black stepped aside so the kings wouldn't be on the same file."},{"q":"Step right back in front of him.","c":"2.Kb2. The kings are face-to-face again, and Black has to move aside. If you played 2.Ka3?, Black could pick between two squares on the a-file and take the opposition."},{"c":"2…Kc8. Black moves alongside you to block your path."},{"q":"Keep going right, staying in front of Black's king. Why not straight forward? Because going forward would lose the opposition.","c":"3.Kc2. The opposition is still yours."},{"c":"3…Kd8."},{"q":"Keep moving right.","c":"4.Kd2."},{"c":"4…Ke8."},{"q":"Stay face-to-face with him.","c":"5.Ke2."},{"c":"5…Kf8. Black's king is already near the target squares."},{"q":"A little more to the right.","c":"6.Kf2."},{"c":"6…Kg8."},{"q":"Step onto the g-file, right in the middle between the target squares.","c":"7.Kg2! Your king stands on the g-file, right between the target squares f8 and h8. Now when it moves forward, one of those target squares will always be within reach."},{"c":"7…Kh8. Black's king stepped to the edge. In the next chapter you'll see how to reach the goal."}],"end":"Opposition: when kings face each other with an odd number of squares between them, the player whose turn it is has to step aside. You want that to be your opponent."},"outflank":{"title":"Outflanking: sneaking past the enemy king","intro":"Let's continue. Your king is on g2 and wants to reach f8, g8, or h8. If it only walks straight ahead, Black's king will block the road. Outflanking helps: your king steps diagonally past the opponent's king and gives away the opposition for a moment. Opposition isn't the final goal—it's just a tool. The real goal is moving forward.","moves":[{"q":"Move forward diagonally, not straight ahead.","c":"8.Kf3! The king steps diagonally forward. Black can take the opposition, but your king sneaks farther up the board."},{"c":"8…Kg7. Black comes to meet you."},{"q":"Stand face-to-face with him again.","c":"9.Kg3! You have the opposition again, and you're one rank higher! Moves like 9.Kf4? Kf6 or 9.Kg4? Kg6 would get you stuck."},{"c":"9…Kf7."},{"q":"Go around him on the other side.","c":"10.Kh4! Another outflank, this time along the edge."},{"c":"10…Kg6. Black stepped in front of you."},{"q":"How do you force him to move aside?","c":"11.Kg4. Opposition! Black has to step sideways."},{"c":"11…Kh6."},{"q":"Black stepped to the edge. Slip past him and move forward.","c":"12.Kf5. Your king is already on the 5th rank."},{"c":"12…Kg7."},{"q":"Opposition!","c":"13.Kg5."},{"c":"13…Kf7."},{"q":"Go around him along the edge.","c":"14.Kh6. You're on the 6th rank."},{"c":"14…Kg8."},{"q":"Step right in front of him.","c":"15.Kg6. Black has to move aside again."},{"c":"15…Kf8."},{"q":"One step closer to the goal.","c":"16.Kh7. The h8 square is right there, and Black can no longer guard it."},{"c":"16…Kf7."},{"q":"Reach the goal!","c":"17.Kh8. You made it! In exactly 17 moves."}],"end":"Outflanking: sometimes you have to give your opponent the opposition for a moment so your king can sneak past and move forward. First head toward the side where your goal is, then outflank."},"kpwin":{"title":"King in front of the pawn wins","intro":"You have a king and a pawn against a lone king. You win when your king marches ahead of the pawn and takes control of the promotion square e8. The rule: send your king as far forward as you can and leave the pawn behind. The pawn has spare moves saved up so you can take the opposition whenever you need it. The kings are facing each other and it is Black's turn, so the opposition is yours.","moves":[{"c":"1…Kd5. Black had to step aside."},{"q":"Black stepped to the left. Which do you move, the king or the pawn?","c":"2.Kf4! The king moves forward past the black king. The pawn waits."},{"c":"2…Kd6."},{"q":"Keep moving the king forward!","c":"3.Kf5. Your king is on the 5th rank."},{"c":"3…Ke7."},{"q":"Put your king face-to-face with the black king. Why? So he has to step aside.","c":"4.Ke5. Opposition! Black has to move."},{"c":"4…Kf7."},{"q":"Black stepped aside. Slip past him and move forward.","c":"5.Kd6. Your king is on the 6th rank, close to e8."},{"c":"5…Kf6."},{"q":"Your king is far out in front. Now the pawn can move.","c":"6.e4. The pawn follows the king."},{"c":"6…Kf7."},{"q":"Push the pawn again.","c":"7.e5."},{"c":"7…Ke8."},{"q":"Don't touch the pawn right now! Place your king so Black's king has to move aside.","c":"8.Ke6! Opposition! If you played 8.e6?, then 8…Kd8 gives Black the opposition. Draw."},{"c":"8…Kd8."},{"q":"Claim the square right next to the promotion square.","c":"9.Kf7! Your king guards e8. The pawn will march e6, e7, e8 and turn into a queen."}],"end":"With a king and pawn, you win when your king marches ahead of the pawn. Send the king as far forward as possible, keep the pawn back, and take the opposition at the key moment."},"kpdef":{"title":"Defense: stand in front of the pawn","intro":"Now you are playing Black and you are down a pawn. You can still hold a draw if you guard the promotion square e8. The rule: whenever you can, hop in front of the pawn. When you can't, step straight backward. Then when White's king walks up, step face-to-face with it and the opposition will be yours.","moves":[{"c":"1.Kf2. White's king steps aside to let the pawn move forward."},{"q":"White's king moved away. Where do you step back to stay in front of the pawn?","c":"1…Ke5. You stepped straight back and stayed right in front of the pawn. Watch out for 1…Kd3?? 2.Kf3—your king would no longer be in front of the pawn and White would promote it."},{"c":"2.Kf3."},{"q":"White's king moves forward. Stand face-to-face with it!","c":"2…Kf5. Opposition! White's king cannot get any farther."},{"c":"3.e4+. The pawn gives check."},{"q":"Where now? Hop in front of the pawn!","c":"3…Ke5. You're right back in front of the pawn."},{"c":"4.Ke3. White has the opposition, so Black has to step back."},{"q":"You can't step in front of the pawn right now. Step straight backward!","c":"4…Ke6! Straight back. When White's king walks up, you will step face-to-face with it."},{"c":"5.Kf4."},{"q":"White's king stepped up. What do you do?","c":"5…Kf6! The opposition is yours again."},{"c":"6.e5+."},{"q":"Hop in front of the pawn!","c":"6…Ke6."},{"c":"7.Ke4. White has the opposition."},{"q":"You cannot go forward. Step straight backward.","c":"7…Ke7."},{"c":"8.Kd5. White's king is trying to go around you."},{"q":"Step right in front of him! Which move is it?","c":"8…Kd7! Opposition! After 8…Kf7??, White plays 9.Kd6 and gets in front of the pawn."},{"c":"9.e6+."},{"q":"Hop in front of the pawn.","c":"9…Ke7."},{"c":"10.Ke5. White has the opposition. Here comes the most important move."},{"q":"Step straight backward. Why not to the side? Because White's king would sneak into d6 or f6.","c":"10…Ke8! The only good move. After 10…Kd8?? 11.Kd6 Ke8 12.e7, White's king takes over e8 and wins."},{"c":"11.Kf5. White checks if you'll make a mistake."},{"q":"Hop in front of the pawn!","c":"11…Ke7. Against 11…Kd8?? or 11…Kf8??, White plays 12.Kf6 and wins."},{"c":"12.Ke5."},{"q":"White has the opposition. Where do you step back?","c":"12…Ke8!"},{"c":"13.Kf6."},{"q":"Stand face-to-face with him!","c":"13…Kf8. Opposition."},{"c":"14.e7+."},{"q":"Where must the king go?","c":"14…Ke8. The only legal move."},{"c":"15.Ke6. Stalemate! Black's king has nowhere to move and is not in check. Draw."}],"end":"Defending against a king and pawn: stay in front of the pawn. When you can't, step straight back. When White's king walks up, face it directly. Practice this until you can do it with your eyes closed!"},"rook1":{"title":"Rook pawn: king in the corner","intro":"A rook pawn is a pawn on the a-file or h-file. Different rules apply to it! White's king is standing in front of the pawn, yet White still cannot win. Why? Black's king hides in the corner, and nobody can chase it out. You are playing Black.","moves":[{"c":"1.h4."},{"q":"Where do you go? Stay right by the corner.","c":"1…Kg8. You don't even have another move."},{"c":"2.h5."},{"q":"Go back into the corner.","c":"2…Kh8."},{"c":"3.Kg6."},{"q":"The king has to move aside. Where?","c":"3…Kg8. Only move, and it's all you need."},{"c":"4.h6."},{"q":"Back to the corner!","c":"4…Kh8."},{"c":"5.h7. Stalemate! Black's king has nowhere to move. Draw."}],"end":"You cannot chase a king out of the corner in front of a rook pawn. If your king reaches the corner ahead of your opponent's rook pawn, it's a draw."},"rook2":{"title":"Rook pawn: stalemate with no pieces","intro":"White's king is on h7, right next to the promotion square. Black only has a king, yet can still make a draw! You just have to trap White's king inside the corner so it cannot get out. You are playing Black.","moves":[{"c":"1.h6."},{"q":"Where will you go? Trap White's king in the corner.","c":"1…Kf8. Black's king guards g8 and g7."},{"c":"2.Kh8."},{"q":"White's king is trapped. Stay close to it.","c":"2…Kf7."},{"c":"3.h7."},{"q":"Last move. Where?","c":"3…Kf8. Stalemate! White's king cannot move and neither can the pawn."}],"end":"Against a rook pawn, sometimes all you need is to lock the enemy king in the corner. It can't get out, and the game ends in stalemate."},"lucena":{"title":"The Lucena Position: building a bridge","intro":"Rook endgames happen more often than any other kind. This is the most important one of all. Your b7 pawn is almost ready to promote, but your king is stuck in front of it on b8 and can't get out. If it steps out, Black's rook will give check after check. A trick called building a bridge will save the day.","moves":[{"q":"First push Black's king as far away from the pawn as possible. How?","c":"1.Rd2+! With check, you push Black's king onto the e-file. If it went to c6, your king would step to c8 and win right away."},{"c":"1…Ke7."},{"q":"Place your rook on the 4th rank. Why there? Later you'll use it to block the checks.","c":"2.Rd4! This is how you start building the bridge. If the king walked out right away with 2.Kc7, Black's rook would check it back inside."},{"c":"2…Ke6. Black's king comes back."},{"q":"Now the king can step out.","c":"3.Kc7. The king finally escapes."},{"c":"3…Rc1+. Here come the checks."},{"q":"Step out of check while still protecting your pawn.","c":"4.Kb6."},{"c":"4…Rb1+."},{"q":"Where do you step away?","c":"5.Kc6. If Black kept checking with 5…Rc1+, White plays 6.Kb5 Rb1+ 7.Rb4 and the bridge is ready."},{"c":"5…Rb2. Black stopped checking."},{"q":"Push Black's king even farther away.","c":"6.Re4+! The king has to go even farther from the pawn. Watch out for the trap 6.Rd5?? Rxb7, which is a draw!"},{"c":"6…Kf5."},{"q":"Put your rook on the c-file. Why? To shield your king when it goes to c7.","c":"7.Rc4! The bridge is built! Your king will go to c7, the rook will block the checks, and the pawn will promote."}],"end":"Lucena Position: push the enemy king aside with check, place your rook on the 4th rank, and later block the checks with it. That's called building a bridge."},"passive":{"title":"A passive rook loses","intro":"Black's rook is sitting on the back rank, just waiting. We call that a passive rook. It looks like it's guarding the whole rank, but it isn't. Watch why!","moves":[{"q":"Swing your rook to the other side of Black's king. Where?","c":"1.Ra7! The rook threatens checkmate on a8. Black's g8 rook is too far away to help."},{"c":"1…Kb8. The king attacks your rook."},{"q":"Your rook is attacked. What do you do?","c":"2.c7+! Check! Your king protects the a7 rook, so Black cannot take it."},{"c":"2…Kc8."},{"q":"Give check with the rook.","c":"3.Ra8+. The king has to move, and Black's g8 rook will fall."},{"c":"3…Kd7."},{"q":"Take the rook!","c":"4.Rxg8. White won the rook."}],"end":"A passive rook on the back rank cannot guard everything. When your opponent sneaks around to the other side, it loses. Keep your rook active: attack and give checks!"},"center":{"title":"Center pawn: don't rush","intro":"A similar position, except the pawn is on d6. White wins again if the rook gets to the other side of Black's king. Just don't rush with the pawn! The pawn is a shield for your king.","moves":[{"q":"Just like last time: send the rook to the other side of the king.","c":"1.Ra7! If you played 1.d7+?, then 1…Kd8 stops your rook from reaching the a-file. Draw."},{"c":"1…Kb8. The king attacks the rook."},{"q":"Your rook is attacked. Give check!","c":"2.Rb7+."},{"c":"2…Ka8. On 2…Kc8? White plays 3.d7+."},{"q":"Move the rook far away from Black's king, to a safe square.","c":"3.Rb1. The rook is safe, and Black's king is trapped in the corner."},{"c":"3…Rc8+. Otherwise White plays Kc7, d7, and d8=Q."},{"q":"Step out of check, closer to your pawn.","c":"4.Kd7."},{"c":"4…Rc2."},{"q":"The king marches in front of the pawn.","c":"5.Ke7."},{"c":"5…Re2+."},{"q":"Where do you step out of check?","c":"6.Kd8. Now the king stands in front of the pawn."},{"c":"6…Rd2."},{"q":"Now the pawn can move forward.","c":"7.d7."},{"c":"7…Re2."},{"q":"Put your rook on the 4th rank. Remember the Lucena Position?","c":"8.Rb4! It's the Lucena Position! White will build the bridge and win."}],"end":"Your pawn is a shield for your king. Don't push it until the decisive moment. Get your rook and king ready first."},"philidor":{"title":"The Philidor Defense","intro":"You are playing Black and you are down a pawn. White's king and pawn are far forward, and White's rook is active. It looks bad, but over 200 years ago a master named Philidor showed how to defend it. Your rook will stop White's king on the 6th rank.","moves":[{"q":"Put your rook on the 6th rank. Why there? White's king won't be able to cross it.","c":"1…Rg6! White's king cannot step onto the 6th rank because it would be in check."},{"c":"2.Rh7+."},{"q":"Where should the king go? Stay near the promotion square.","c":"2…Ke8."},{"c":"3.e6. White had to push the pawn because the king couldn't get through."},{"q":"The pawn moved forward. Now send your rook all the way to the back. Why? From there it will give checks.","c":"3…Rg1! White's king no longer has a hiding spot behind the pawn."},{"c":"4.Kd6. White threatens checkmate on h8."},{"q":"Give check!","c":"4…Rd1+."},{"c":"5.Ke5."},{"q":"Another check.","c":"5…Re1+."},{"c":"6.Kd6."},{"q":"And check again!","c":"6…Rd1+. White's king cannot hide from the checks. It's a draw!"}],"end":"Philidor Defense: while White's pawn is still back, keep your rook on the 6th rank. Once the pawn pushes forward, move your rook to the back and give checks."},"trade":{"title":"Should you trade queens?","intro":"White is up a pawn. If you trade queens, you'll reach a rook endgame. Can you defend it? Yes, if you remember the Philidor Defense from the last chapter! You are playing Black.","moves":[{"q":"Offer a queen trade with check.","c":"1…Qd7+."},{"c":"2.Qxd7+. Against 2.Qd6, Black plays 2…Rd1+ 3.Rd4 Rxd4+ 4.Kxd4 Qxd6+ 5.exd6 Kd7 and the pawn endgame is a draw."},{"q":"Take the queen back.","c":"2…Kxd7."},{"c":"3.Rf7+."},{"q":"Where should the king go? In front of the pawn.","c":"3…Ke8."},{"c":"4.Ke6. White's king is on the 6th rank."},{"q":"Get your rook behind White's pawn. Why? From behind it holds the pawn back, and White's king has nowhere to hide.","c":"4…Re1! The rook stands behind the pawn and stops it from moving forward. White's king has no shelter."},{"c":"5.Ra7. White threatens checkmate on a8."},{"q":"Escape the checkmate threat. Which side? The short side.","c":"5…Kf8! The king steps to the short side of the board. That leaves lots of room on the long side for the rook to give side checks."},{"c":"6.Ra8+."},{"q":"Step out of check.","c":"6…Kg7."},{"c":"7.Re8. White blocked the e-file and wants to push the pawn."},{"q":"Swing your rook to the long side. Why? From there it will check from the side.","c":"7…Ra1! When White's king steps out, your rook will give checks from the side. It's a draw!"}],"end":"Before trading pieces, picture what endgame you will get. If you know how to defend it—like with the Philidor Defense—you can trade happily."},"dopp":{"title":"Distant opposition","intro":"You already know king and pawn vs. king. Here Black has the extra pawn and you are defending. The kings are far apart. Opposition still works even from far away: when they stand on the same file with three (or five) empty squares between them, your opponent is forced to move first. This is called distant opposition.","moves":[{"q":"Put your king on the same file as Black's king – with three empty squares between them.","c":"1.Kd1! Between the kings are d2, d3, and d4 – three empty squares. The opposition is yours! Playing 1.Ke2? Ke4 gives Black the opposition."},{"c":"1…Ke4."},{"q":"Black's king stepped aside. Step right back in front of it.","c":"2.Ke2! Now it's direct opposition: one square between the kings, and it's Black's turn."},{"c":"2…Kd4. Black cannot break through. Draw!"}],"end":"Distant opposition: when the kings are far apart, step onto the same file with an odd number of squares between them. When they get close, the opposition will stay yours."},"qvp":{"title":"Queen against a pawn","intro":"Black's e2 pawn is one step from promoting. Even so, your queen can stop it! The plan: use checks and pins to force Black's king to step in front of its own pawn. When the king blocks its own pawn, your king gets time to walk closer.","moves":[{"q":"Attack the e2 pawn with your queen.","c":"1.Qd3! The queen attacks the pawn. Black has to guard it with the king."},{"c":"1…Kf2."},{"q":"Pin the pawn to the black king.","c":"2.Qd2. The pawn is pinned to the king."},{"c":"2…Kf1."},{"q":"Give check to the king.","c":"3.Qf4+."},{"c":"3…Ke1. The king had to step in front of the pawn."},{"q":"The king is standing in front of the pawn. Place your queen so it cannot go to d2 or f2.","c":"4.Qe3. The queen guards both d2 and f2. The king has to step to d1."},{"c":"4…Kd1."},{"q":"Check! Force the king back in front of the pawn.","c":"5.Qd3+."},{"c":"5…Ke1. The king is in front of the pawn again – the pawn cannot move forward."},{"q":"The king is blocking its pawn. Now you have time – bring your own king closer!","c":"6.Ke4! Your king uses the free turn to walk closer. Keep repeating this until your king arrives and wins!"}],"end":"Queen against a pawn: use checks to force the enemy king in front of its pawn, then use that turn to bring your own king closer. Careful: against a pawn on a2, c2, f2, or h2 this might not work – see the next chapter!"},"qvpa":{"title":"Queen against a rook pawn","intro":"Black's pawn is on a2. Against an edge pawn, Black has a sneaky trick: the king goes to the a1 corner, and if the queen traps it there, it's stalemate! You must stop Black's king from reaching the corner.","moves":[{"q":"Put your queen on the long diagonal to guard the a1 corner.","c":"1.Qg7! The queen watches the whole diagonal down to a1. Black's king cannot enter the corner. Checking with 1.Qb5+? would be a mistake: Kc2 2.Qa4+ Kb1 3.Qb3+ Ka1, and if you trap the king it's stalemate."},{"c":"1…Kc2."},{"q":"The king is walking away. Catch the pawn in a trap!","c":"2.Qa1. The queen stands right on the promotion square in front of the pawn. The pawn will fall."}],"end":"Against a rook pawn (a-file or h-file), don't let the enemy king into the corner – or it will escape with stalemate!"},"qvr":{"title":"Queen against a rook: a long-range fork","intro":"Black's h7 rook is far away from its king. The queen can win it with a series of checks that ends in a fork: a check to the king that attacks the rook at the same time. A queen can fork from all the way across the board!","moves":[{"q":"Give check and push the king into the corner.","c":"1.Qe5+! On 1…Kc8, White plays 2.Qe8 checkmate."},{"c":"1…Ka8."},{"q":"Another check – from the other side.","c":"2.Qa1+."},{"c":"2…Kb8."},{"q":"Now look closely: find the check that also attacks the h7 rook!","c":"3.Qb1+!! A check along the b1–h7 diagonal with the rook sitting at the other end. A fork from the opposite corner of the board!"},{"c":"3…Ka7."},{"q":"Take the rook!","c":"4.Qxh7+. The rook falls, and White will soon give checkmate."}],"end":"Against a rook separated from its king, look for a check that also attacks the rook. A queen can fork from all the way across the board!"},"rbehind":{"title":"The rook belongs behind a passed pawn","intro":"Your a7 pawn is almost a queen. Black's a2 rook attacks it from behind and guards the promotion square. Here is a golden rule: the rook belongs BEHIND a passed pawn – both behind your own pawn and behind your opponent's pawn. From behind, it protects the pawn and pushes it forward.","moves":[{"q":"First give check to chase the king away.","c":"1.Rd5+! The check drives Black's king away."},{"c":"1…Kf4."},{"q":"Put your rook behind your pawn – from the other side.","c":"2.Ra5! Your rook stands behind the a7 pawn and protects it. Black's rook can no longer take it, and your king can come help. Playing 1.Kb7? Kf4 2.a8=Q Rxa8 3.Kxa8 g3 would let Black's pawn race through."}],"end":"The rook belongs behind a passed pawn – behind your own to push it forward, and behind your opponent's to hold it back."},"cutoff":{"title":"Cut the king off from the pawn","intro":"A rook and pawn against a rook is usually a draw if the defending king gets in front of the pawn. Black's king is on f8 and wants to reach d8. Stop it!","moves":[{"q":"Put your rook where Black's king cannot cross the e-file.","c":"1.Re1! The rook cuts off Black's king along the e-file. Now it can never reach the pawn. After 1.d6? Ke8, the king gets in front of the pawn and holds a draw."},{"c":"1…Rc2. Now White brings the king and pawn up and wins."}],"end":"In a rook endgame, cut the enemy king off from the pawn – usually by placing your rook on the file next to the pawn."}}}};
const DATEL_EN = {};

function trSrc(s){
  if (!s || typeof s !== "string") return s;
  return s
    .replace(/^zisk figúrky$/i, "win a piece")
    .replace(/Mat 1 ťahom/g, "Mate in 1")
    .replace(/Mat 2 ťahmi/g, "Mate in 2")
    .replace(/Mat 3 ťahmi/g, "Mate in 3")
    .replace(/úloha (\d+)/g, "puzzle $1")
    .replace(/problém /g, "problem ")
    .replace(/cvičenie (\d+)/g, "exercise $1")
    .replace(/súťaž (\d+)/g, "contest $1")
    .replace(/kap\.\s*(\d+)/g, "ch. $1")
    .replace(/kapitola (\d+)/g, "chapter $1")
    .replace(/stupeň/g, "level")
    .replace(/pracovný list/gi, "worksheet")
    .replace(/Dvojitý útok/g, "Double attack")
    .replace(/Väzba/g, "Pin")
    .replace(/Vidlička/g, "Fork")
    .replace(/Odkrytý útok/g, "Discovered attack")
    .replace(/Odkrytý šach/g, "Discovered check")
    .replace(/Dvojitý šach/g, "Double check")
    .replace(/Röntgen/g, "Skewer")
    .replace(/Obrana/g, "Defense")
    .replace(/Koncovka/g, "Endgame")
    .replace(/Dáma/g, "Queen")
    .replace(/Veža/g, "Rook")
    .replace(/Strelec/g, "Bishop")
    .replace(/Jazdec/g, "Knight")
    .replace(/Pešiak/g, "Pawn")
    .replace(/Kráľ/g, "King");
}

let globalsDone = false;
window.I18N_APPLY_CONTENT = function(studiesObj){
  if (!window.I18N || !window.I18N.isEn()) return;
  if (!globalsDone){
    globalsDone = true;
    if (window.OPENING_PLANS && OPENINGS_EN.plans){
      for (const [k, v] of Object.entries(OPENINGS_EN.plans)){
        if (window.OPENING_PLANS[k]) Object.assign(window.OPENING_PLANS[k], v);
      }
    }
    if (Array.isArray(window.OPENING_BOOK) && Array.isArray(OPENINGS_EN.book)){
      for (let i = 0; i < window.OPENING_BOOK.length && i < OPENINGS_EN.book.length; i++){
        window.OPENING_BOOK[i][2] = OPENINGS_EN.book[i];
      }
    }
    if (window.HROZBY){
      for (const arr of Object.values(window.HROZBY)){
        if (Array.isArray(arr)) for (const it of arr) if (it && it.src) it.src = trSrc(it.src);
      }
    }
    for (const [key, list] of Object.entries(DATEL_EN)){
      const arr = window[key];
      if (!Array.isArray(arr)) continue;
      const byId = new Map(list.map(x => [x.id, x]));
      for (const g of arr){
        const tr = byId.get(g.id);
        if (tr){
          if (tr.t) g.t = tr.t;
          if (tr.d) g.d = tr.d;
          if (tr.h1) g.h1 = tr.h1;
        }
        if (Array.isArray(g.items)) for (const it of g.items) if (it && it.s) it.s = trSrc(it.s);
      }
    }
  }
  if (studiesObj){
    const allEn = Object.assign({}, STUDIES_EN, window.PUBLIC_OPENING_STUDIES_EN || {});
    for (const [sid, stEn] of Object.entries(allEn)){
      const st = studiesObj[sid];
      if (!st) continue;
      st.name = stEn.name;
      st.intro = stEn.intro;
      for (const ch of (st.chapters || [])){
        const ce = stEn.chapters[ch.id];
        if (!ce) continue;
        ch.title = ce.title;
        ch.intro = ce.intro;
        ch.end = ce.end;
        if (Array.isArray(ch.moves) && Array.isArray(ce.moves)){
          for (let i = 0; i < ch.moves.length && i < ce.moves.length; i++){
            if (ce.moves[i].q !== undefined) ch.moves[i].q = ce.moves[i].q;
            if (ce.moves[i].c !== undefined) ch.moves[i].c = ce.moves[i].c;
          }
        }
      }
    }
  }
};
})();
